import React, { useRef, useEffect } from 'react';
import './TrainingMonitor.css';

function MultiLineChart({ data, title, labels, colors, height = 200 }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !data || Object.keys(data).length === 0) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const chartHeight = canvas.height;

    // Clear canvas
    ctx.fillStyle = '#0a0a0f';
    ctx.fillRect(0, 0, width, chartHeight);

    // Draw grid
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = (i / 5) * chartHeight;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    for (let i = 0; i <= 10; i++) {
      const x = (i / 10) * width;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, chartHeight);
      ctx.stroke();
    }

    // Find global min/max across all series
    const allValues = Object.values(data).flat();
    if (allValues.length === 0) return;

    const minVal = Math.min(...allValues, 0);
    const maxVal = Math.max(...allValues, 1);
    const range = maxVal - minVal || 1;

    // Draw each series
    Object.keys(data).forEach((key, idx) => {
      const series = data[key];
      if (!series || series.length === 0) return;

      const color = colors[idx] || '#ffffff';

      ctx.beginPath();
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;

      series.forEach((val, i) => {
        const x = (i / Math.max(series.length - 1, 1)) * width;
        const y = chartHeight - ((val - minVal) / range) * chartHeight;

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });

      ctx.stroke();

      // Draw last point
      if (series.length > 0) {
        const lastVal = series[series.length - 1];
        const x = width;
        const y = chartHeight - ((lastVal - minVal) / range) * chartHeight;

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    });

  }, [data, colors]);

  return (
    <div className="multi-line-chart glass-dark">
      <div className="chart-header">
        <h4>{title}</h4>
        <div className="chart-legend">
          {labels.map((label, idx) => (
            <div key={label} className="legend-item-inline">
              <div
                className="legend-dot"
                style={{ background: colors[idx] }}
              />
              <span>{label}</span>
            </div>
          ))}
        </div>
      </div>
      <canvas
        ref={canvasRef}
        width={800}
        height={height}
        className="chart-canvas"
      />
    </div>
  );
}

function TrainingMonitor({ history, config, metrics }) {
  const lossData = {
    loss: history.loss || []
  };

  const alignmentData = {
    alignment: history.alignment || []
  };

  const reconstructionData = {
    reconstruction: history.reconstruction || []
  };

  return (
    <div className="training-monitor">
      <div className="monitor-header">
        <h2>Training Monitor</h2>
        <div className="training-status">
          <div className="status-badge active">
            <div className="status-pulse" />
            <span>Training Active</span>
          </div>
        </div>
      </div>

      <div className="monitor-grid">
        {/* Loss Curves */}
        <div className="monitor-section full-width">
          <MultiLineChart
            data={lossData}
            title="InfoNCE Contrastive Loss"
            labels={['Loss']}
            colors={['#7b2ff7']}
            height={180}
          />
        </div>

        <div className="monitor-section full-width">
          <MultiLineChart
            data={alignmentData}
            title="Cross-Sensor Embedding Alignment"
            labels={['Cosine Similarity']}
            colors={['#00d4ff']}
            height={180}
          />
        </div>

        <div className="monitor-section full-width">
          <MultiLineChart
            data={reconstructionData}
            title="Surface Reconstruction Error"
            labels={['Chamfer Distance']}
            colors={['#ff6b00']}
            height={180}
          />
        </div>

        {/* Configuration Panel */}
        <div className="monitor-section glass-dark">
          <h3>Training Configuration</h3>
          <div className="config-list">
            <div className="config-item">
              <span className="config-label">Embedding Dimension:</span>
              <span className="config-value mono">{config.embeddingDim}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Temperature (τ):</span>
              <span className="config-value mono">{config.temperature.toFixed(3)}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Learning Rate:</span>
              <span className="config-value mono">{config.learningRate.toFixed(4)}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Augmentation Strength:</span>
              <span className="config-value mono">{config.augmentationStrength.toFixed(2)}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Active Sensors:</span>
              <span className="config-value">{config.activeSensors.join(', ')}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Material:</span>
              <span className="config-value">{config.material}</span>
            </div>
            <div className="config-item">
              <span className="config-label">Task:</span>
              <span className="config-value">
                {config.task.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}
              </span>
            </div>
          </div>
        </div>

        {/* Performance Metrics */}
        <div className="monitor-section glass-dark">
          <h3>Current Performance</h3>
          <div className="performance-grid">
            <div className="performance-item">
              <div className="performance-label">Alignment Score</div>
              <div className="performance-value" style={{ color: '#00d4ff' }}>
                {metrics.alignmentScore.toFixed(4)}
              </div>
              <div className="performance-bar">
                <div
                  className="performance-fill"
                  style={{
                    width: `${Math.min(100, metrics.alignmentScore * 100)}%`,
                    background: '#00d4ff'
                  }}
                />
              </div>
            </div>

            <div className="performance-item">
              <div className="performance-label">Reconstruction Error</div>
              <div className="performance-value" style={{ color: '#ff6b00' }}>
                {metrics.reconstructionError.toFixed(4)}
              </div>
              <div className="performance-bar">
                <div
                  className="performance-fill"
                  style={{
                    width: `${Math.max(0, 100 - metrics.reconstructionError * 100)}%`,
                    background: '#ff6b00'
                  }}
                />
              </div>
            </div>

            <div className="performance-item">
              <div className="performance-label">Insertion Success Rate</div>
              <div className="performance-value" style={{ color: '#20ff40' }}>
                {(metrics.insertionSuccess * 100).toFixed(1)}%
              </div>
              <div className="performance-bar">
                <div
                  className="performance-fill"
                  style={{
                    width: `${metrics.insertionSuccess * 100}%`,
                    background: '#20ff40'
                  }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Training Info */}
        <div className="monitor-section glass-dark full-width">
          <h3>About This Training</h3>
          <div className="training-info">
            <p>
              <strong>Contrastive Learning:</strong> The model uses InfoNCE loss with temperature scaling
              to learn a shared embedding space across heterogeneous tactile sensors. Positive pairs are
              readings from different sensors touching the same object, while negatives are different contacts.
            </p>
            <p>
              <strong>Hard Negative Mining:</strong> The system automatically identifies and prioritizes
              challenging negative examples that are close to the anchor in embedding space but represent
              different contacts.
            </p>
            <p>
              <strong>Domain Randomization:</strong> Input augmentation with controlled noise, dropout,
              and sensor bias simulation improves cross-sensor generalization and sim2real transfer.
            </p>
            <p>
              <strong>Surface Reconstruction:</strong> A PointNet++-style decoder maps learned embeddings
              to 3D surface geometry with per-point normal forces and shear vectors, validated against
              physics-based ground truth.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default TrainingMonitor;
